"""Lighting tab: add lighting circuits and assign them to dimmer channels, DALI drivers and other devices.
Real Worker + front-end, TEST-ONLY Supabase mock."""
import json, sys, urllib.request
from playwright.sync_api import sync_playwright
BASE=sys.argv[1] if len(sys.argv)>1 else 'http://localhost:8799'; MOCK='http://127.0.0.1:54321'; res=[]
def ok(n,c,i=''): res.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n+(' :: '+str(i)[:300] if not c and i else ''))
def post(path,body): return json.loads(urllib.request.urlopen(urllib.request.Request(MOCK+path,json.dumps(body).encode(),{'Content-Type':'application/json'})).read() or b'{}')
post('/__test/reset',{})
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_page(viewport={'width':1366,'height':900}); errs=[]
    pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto(BASE); pg.wait_for_selector('[data-m=register]'); pg.click('[data-m=register]')
    for k,v in dict(first_name='Pat',last_name='Test',email='pat@example.com',password='Passw0rd!!',password2='Passw0rd!!').items(): pg.fill('#'+k,v)
    pg.select_option('#country',index=9); pg.select_option('#occupation','Marine Electrician'); pg.check('#terms'); pg.click('#saGo'); pg.wait_for_selector('text=Check your email')
    post('/__test/confirm',{'email':'pat@example.com'})
    pg.goto(BASE); pg.wait_for_selector('#saForm'); pg.fill('#email','pat@example.com'); pg.fill('#password','Passw0rd!!'); pg.click('#saGo'); pg.wait_for_selector('text=Welcome, Pat')
    pg.click('[data-sa=new]'); pg.wait_for_selector('.wrap',state='visible'); pg.wait_for_timeout(1000)
    pg.evaluate("S.modules.length || (S.modules.push({id:'M1',model:'LQSE-4A-D',phase:'L1',len:10,inSel:0,cable:'pvc',size:'auto'}), refresh(true))")
    mid=pg.evaluate("S.modules.find(m=>(libOf(m.model)||{}).power&&libOf(m.model).zones>=2).id")
    pg.evaluate("S.modules.find(m=>m.id=='%s').name='Saloon dimmer'; S.modules.find(m=>m.id=='%s').area='Main saloon'"%(mid,mid))
    drv=pg.evaluate("DALI_CAT.find(c=>c.k=='driver'&&c.mt=='din').m")
    pg.evaluate("dS().units.push({id:'D1',model:%s,link:'',label:'Dining drivers',area:'Dining'}); S.custom=S.custom||[]; S.custom.push({id:'X1',name:'Blind relay box',note:'',w:2,rating:0,heatW:0,ph:'N',area:'Bridge'}); refresh(true)"%json.dumps(drv))
    ok('Lighting tab exists', 'Lighting' in pg.inner_text('#tabs'))
    pg.evaluate("tab='lighting'; draw(); renderTabs()"); pg.wait_for_selector('[data-a=addl]')
    n0=pg.evaluate("S.circuits.filter(c=>c.type=='lighting').length")
    pg.click('[data-a=addl]'); pg.wait_for_selector('tr[data-row] input[data-f=area]')
    ok('adding creates a lighting circuit', pg.evaluate("S.circuits.filter(c=>c.type=='lighting').length")==n0+1, n0)
    row=pg.locator('tr[data-row]').last
    row.locator('input[data-f=name]').fill('Dining downlights'); row.locator('input[data-f=area]').fill('Dining room'); row.locator('input[data-f=P]').fill('300')
    opts=row.locator('select[data-f=fed]').evaluate("s=>[...s.options].map(o=>o.value+'|'+o.textContent)")
    ok('menu offers dimmer channels, DALI drivers and other devices', any(o.startswith(mid+'|') for o in opts) and any(o.startswith('d:D1') for o in opts) and any(o.startswith('x:X1') for o in opts), opts)
    row.locator('select[data-f=fed]').select_option('d:D1'); pg.wait_for_timeout(400)
    c=pg.evaluate("S.circuits[S.circuits.length-1]")
    ok('circuit stores name, area, load and DALI driver', c['name']=='Dining downlights' and c['area']=='Dining room' and float(c['P'])==300, c)
    ok('circuit is assigned to the DALI driver', c['ctl']=='d:D1' and not c['mod'], c)
    ok('summary lists the driver with its total', 'Dining drivers' in pg.inner_text('#lsum') and '300' in pg.inner_text('#lsum'), pg.inner_text('#lsum'))
    pg.click('[data-a=addl]'); pg.wait_for_timeout(300)
    row=pg.locator('tr[data-row]').last; row.locator('input[data-f=name]').fill('Saloon cove'); row.locator('input[data-f=P]').fill('900')
    row.locator('select[data-f=fed]').select_option('%s|1'%mid); pg.wait_for_timeout(400)
    c2=pg.evaluate("S.circuits[S.circuits.length-1]")
    ok('circuit assigned to a dimmer channel uses mod and zone', c2['mod']==mid and c2['zone']==1 and not c2.get('ctl'), c2)
    ok('over the channel limit is flagged', 'over' in pg.inner_text('#lsum'), pg.inner_text('#lsum'))
    pg.click('[data-a=addl]'); pg.wait_for_timeout(300)
    row=pg.locator('tr[data-row]').last; row.locator('input[data-f=name]').fill('Bridge blinds light'); row.locator('select[data-f=fed]').select_option('x:X1'); pg.wait_for_timeout(400)
    ok('circuit assigned to another device', pg.evaluate("S.circuits[S.circuits.length-1].ctl")=='x:X1')
    pg.evaluate("tab='circuits'; draw(); renderTabs()")
    ok('same circuits show in the Circuits tab with the assignment', pg.evaluate("[...document.querySelectorAll('select[data-f=fed]')].some(s=>s.value=='d:D1')"))
    ok('schedule rows show the device name', pg.evaluate("schedRows().some(r=>String(r[3]).includes('D1'))"))
    pg.evaluate("tab='lighting'; draw(); renderTabs()")
    first=pg.locator('tr[data-row]').filter(has=pg.locator('input[data-f=name][value="Dining downlights"]'))
    first.locator('select[data-f=fed]').select_option('%s|2'%mid); pg.wait_for_timeout(400)
    ok('choosing a dimmer channel clears the driver link', pg.evaluate("(()=>{const c=S.circuits.find(c=>c.name=='Dining downlights'); return c.mod=='%s' && c.zone==2 && !c.ctl})()"%mid))
    pg.evaluate("S.circuits.find(c=>c.name=='Dining downlights').mod=''; S.circuits.find(c=>c.name=='Dining downlights').ctl='d:D1'; refresh(true)")
    ok('deleting the DALI unit clears assignments on reload', pg.evaluate("(()=>{dS().units=[]; fix(); return S.circuits.every(c=>c.ctl!='d:D1')})()"))
    ok('no page errors', not errs, errs)
    b.close()
print('%d/%d passed'%(sum(res),len(res))); sys.exit(0 if all(res) else 1)
